const dialog=document.querySelector('#brief-dialog');
let audience='brand';
function setAudience(value){audience=value;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===value)));const label=document.querySelector('#identity-label');label.firstChild.textContent=value==='brand'?'Brand name':'Social profile';label.querySelector('input').placeholder=value==='brand'?'Your brand or company':'Your Instagram or YouTube profile';document.querySelector('.form-result').textContent='';}
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>{setAudience(b.dataset.open);dialog.showModal();}));
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>setAudience(b.dataset.tab)));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelectorAll('.service-row').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));document.getElementById(b.getAttribute('aria-controls')).hidden=open;b.querySelector('.service-toggle').textContent=open?'+':'−';}));
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open);menu.textContent=open?'×':'☰';});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰';}));
document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const text=['EMPIREX MEDIA — PARTNERSHIP BRIEF','',`Partnership: ${audience==='brand'?'Brand campaign':'Creator partnership'}`,`Name: ${data.get('name')}`,`Email: ${data.get('email')}`,`${audience==='brand'?'Brand':'Social profile'}: ${data.get('identity')}`,'','Plans:',data.get('message'),'','Prepared locally. This brief has not been sent to EmpireX Media.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='EmpireX-Partnership-Brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('.form-result').textContent='Your brief is ready. Keep it for your first conversation with EmpireX.';});
document.querySelector('#year').textContent=new Date().getFullYear();
